import hashlib
import html
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / 'reports/settings-copy-2026-10-05'
capture = json.loads((OUT / 'capture.json').read_text(encoding='utf-8'))
items = []
by_key = {}
sections = {
    'visual': 'Оформление', 'editor': 'Рукопись', 'dictionary': 'Словарь',
    'review': 'Редактура', 'bookmarks': 'Закладки', 'focus': 'Концентрация',
    'macros': 'Макросы', 'formatting': 'Автоформатирование', 'ai': 'ИИ-ассистент',
    'data': 'Сохранение и защита', 'export': 'Экспорт', 'misc': 'Дополнительно',
    'compact': 'Компактный вид', 'search': 'Поиск настроек',
    'new-custom-provider': 'ИИ: свой провайдер', 'new-custom-persona': 'ИИ: своя персона',
    'dictionary-rule': 'Словарь: правило', 'world-rules': 'ИИ: правила мира',
    'navigation': 'Названия разделов', 'internal': 'Параметры без поля в настройках',
    'service': 'Служебное окно Luna', 'backups': 'Копии: вложенное окно',
}


def add(key, section, current, surface, options=None, bounds=None):
    options = [{'value': option['value'], 'label': option['label']} if isinstance(option, dict) else {'value': option[0], 'label': option[1]} for option in options or []]
    options = [option for option in options if option['value'] not in ['AuditFont', 'prov_audit', 'custom_audit']]
    variant = {'surface': surface, **current}
    if key in by_key:
        item = by_key[key]
        if variant not in item['variants']:
            item['variants'].append(variant)
        for option in options or []:
            if option not in item['options']:
                item['options'].append(option)
        return item
    item = {
        'key': key, 'section': section, 'sectionTitle': sections[section],
        'current': current, 'variants': [variant], 'options': options or [],
        'bounds': bounds or [], 'default': capture['defaults'].get(key),
        'proposed': dict(current), 'rationale': [], 'notes': '', 'blocked': False,
        'sources': [], 'kind': 'setting',
    }
    by_key[key] = item
    items.append(item)
    return item


def copy_of(row):
    return {name: row.get(source, '') for name, source in [('title', 'title'), ('short', 'short'), ('long', 'long')]}


for surface in capture['surfaces']:
    tab = surface['tab']
    if tab in ['ai-custom', 'editor-custom-font', 'dictionary-variants', 'edit-custom-provider', 'edit-custom-persona']:
        section = {'ai-custom': 'ai', 'editor-custom-font': 'editor', 'dictionary-variants': 'dictionary',
                   'edit-custom-provider': 'new-custom-provider', 'edit-custom-persona': 'new-custom-persona'}[tab]
    else:
        section = tab
    location = f"{surface['platform']} · {tab}"
    for row in surface['rows']:
        if row['title'] == 'Группы контекста':
            add('aiContextGroups', section, copy_of(row), location)['kind'] = 'group'
            for key, label in [('aiContextCharacters', 'Characters'), ('aiContextLocations', 'Locations'),
                               ('aiContextTimeline', 'Timeline'), ('aiContextSubtimelines', 'Subtimelines'), ('aiContextNotes', 'Notes')]:
                add(key, section, {'title': label, 'short': '', 'long': ''}, location)
            continue
        key = (row['keys'] or row['actions'] or [next((c['id'] for c in row['controls'] if c['id']), '')])[0]
        key = {'set-accent-preset': 'accent', 'toggle-card-view': 'cardView', 'toggle-nocturned-export': 'exportNocturned'}.get(key, key)
        current = copy_of(row)
        if not current['title']:
            if key == 'show-whats-new': current['title'] = 'Что нового?'
            elif key == 'delete-custom-font': current['title'] = 'Удалить'
        if not key:
            raise ValueError(f'Unidentified setting row: {row}')
        item = add(key, section, current, location, row['options'], row['controls'])
        if not row['keys']:
            item['kind'] = 'action'
    for extra in surface['extra']:
        key = extra.get('action') or extra.get('key')
        if extra.get('preset'):
            key += ':' + extra['preset']
        if extra.get('filter'):
            key = 'dictionary-filter:' + extra['filter']
        if not key:
            continue
        if section == 'dictionary-rule':
            key = 'rule:' + key
        elif section in ['new-custom-provider', 'new-custom-persona']:
            key = ('provider:' if section == 'new-custom-provider' else 'persona:') + key
        key = {'toggle-nocturned-export': 'exportNocturned'}.get(key, key)
        current = copy_of(extra)
        if (section in ['misc', 'data'] or (section == 'dictionary' and extra.get('action') not in ['dictionary-import', 'dictionary-export', 'dictionary-add'])) and current['short']:
            current['contextShort'] = current['short']
            current['short'] = ''
        if key == 'dictionarySearch' and not current['title']:
            current['title'] = extra.get('placeholder') or ''
        if key == 'settings-search-field' and not current['title']:
            current['title'] = extra.get('placeholder') or ''
        item = add(key, section, current, location, extra['options'])
        if extra.get('action'):
            item['kind'] = 'action'
        if extra.get('maxLength'):
            item['bounds'] = [{'maxLength': extra['maxLength']}]
        if extra.get('placeholder'):
            item['placeholder'] = extra['placeholder']
    for mode in surface['modes']:
        add('reviewMode:' + mode['value'], 'review', {'title': mode['title'], 'short': mode['short'], 'long': ''}, location)['kind'] = 'choice'

for registry in capture['registry']:
    key = {'compactSettingsMenu': 'open-compact-settings', 'worldRules': 'edit-world-rules'}.get(registry['key'], registry['key'])
    if key not in by_key:
        raise ValueError('Registry control missing from rendered inventory: ' + key)
    add(key, by_key[key]['section'], {'title': registry['label'], 'short': registry.get('note', ''), 'long': registry.get('note', '')}, 'Поиск настроек', registry.get('options', []))

SPECS = '''
theme|=|Цветовая палитра интерфейса.|Выберите одну из восьми тем. Тема меняет цвета интерфейса, а акцентный цвет настраивается отдельно. Содержимое рукописи остаётся прежним.
accent|Акцентный цвет|Цвет кнопок, меток и подсветки.|Выберите цвет из палитры или введите шестизначный HEX-код. Один акцент используется во всём интерфейсе. «Сброс» возвращает #8B5CF6, а не индивидуальный цвет выбранной темы.
windowMaterial|Размытие фона панелей|Полупрозрачный фон меню и панелей.|Включает оформление панелей с прозрачностью и размытием средствами интерфейса. Сейчас настройка не подключает системные материалы Mica или Vibrancy и не делает окно Electron прозрачным.
cursorGlow|Свечение каретки|Мягкое свечение у позиции ввода.|Подсветка помогает найти каретку в рабочем тексте. Она относится к курсору ввода, а не к указателю мыши. Форма и анимация каретки настраиваются отдельно.
caretStyle|Форма каретки|Тонкая линия, блок или подчёркивание.|Меняет вид каретки в редакторе рукописи. Выбор блока или подчёркивания не включает режим замены символов: текст по-прежнему вставляется обычным способом.
caretBlink|Период мигания каретки|Длительность цикла в миллисекундах.|Допустимо от 250 до 1400 мс с шагом 10 мс. Чем больше значение, тем медленнее анимация. При включённом «Плавном дыхании» тот же период используется для изменения прозрачности.
caretBreath|=|Плавное изменение яркости вместо резкого мигания.|Каретка мягко появляется и затухает. Длительность задаётся параметром «Период мигания каретки». Настройка не влияет на анимации меню и панелей.
textContrast|Контраст текста рукописи|Яркость текста относительно фона страницы.|Диапазон — от 45 до 100 %. В светлой теме увеличение значения делает текст темнее, в тёмных — светлее. Цвета остального интерфейса этим ползунком не меняются.
open-compact-settings|=|Настройте плотность отдельных частей интерфейса.|Открывает отдельное окно с шестью независимыми переключателями: документы, база знаний, карточки, инструменты, настройки и заметки. Компактность каждой части можно включить отдельно.
typewriterMode|=|Держать строку с кареткой ближе к центру экрана.|Редактор прокручивает рабочую область вслед за позицией ввода. У начала и конца текста центрирование ограничено доступным пространством прокрутки. Настройка не меняет разбиение на страницы.
reduceMobileAnimations|Уменьшить анимации|Сократить движение интерфейса на телефоне.|Доступно в Android-приложении. Большинство переходов становятся короче, а отдельные декоративные эффекты отключаются. По умолчанию настройка выключена; она действует вместе с системным предпочтением уменьшенного движения.
open-shortcuts|=|Справка по сочетаниям клавиш приложения.|Открывает список доступных команд и их сочетаний. Сочетания здесь нельзя переназначить; собственные комбинации для вставки текста создаются в разделе «Макросы».
fontFamily|=|Шрифт текста в редакторе.|Выберите встроенное семейство или ранее загруженный шрифт. Выбор относится к отображению рукописи; PDF и DOCX используют свои правила оформления. Загрузка файла сама по себе не выбирает новый шрифт.
custom-font-uploader|Добавить шрифт|Файл WOFF2, WOFF, TTF или OTF.|Шрифт сохраняется локально вместе с настройками и появляется в списке шрифтов рукописи. Его имя берётся из названия файла. После загрузки выберите его в поле «Шрифт рукописи»; файл с уже существующим именем повторно не добавляется.
delete-custom-font|Удалить загруженный шрифт|Убрать выбранный файл из списка шрифтов.|Удаляется только добавленный пользователем шрифт. Если он выбран для рукописи, настройка возвращается к Lora. В текущем коде визуальное применение замены может потребовать повторного применения настроек.
fontSize|=|Размер основного текста в пикселях.|Диапазон — 14–26 px с шагом 1 px. Заголовки имеют собственные размеры. Для нового профиля используются 16 px на компьютере и 18 px в мобильном интерфейсе.
lineHeight|=|Высота строки относительно размера шрифта.|Диапазон — 1,35–2,25 с шагом 0,05. Например, интервал 1,5 при размере 16 px даёт строку высотой 24 px. Заголовки оформляются отдельно; исходное значение нового мобильного профиля — 1,7.
letterSpacing|=|Дополнительное расстояние между буквами.|Диапазон — от 0 до 1,8 px с шагом 0,1 px. Настройка меняет отображение текста в рукописи, но не добавляет пробелы или другие символы в документ.
paragraphSpacing|=|Вертикальный промежуток после абзаца.|Диапазон — 0,25–2,2 em с шагом 0,05. Единица em зависит от размера шрифта: 1 em при 16 px равен 16 px. Настройка применяется к абзацам и цитатам, а не одинаково ко всем типам блоков.
paragraphIndent|Красная строка|Отступ первой строки обычного абзаца.|Добавляет отступ первой строки размером 2,2 em. Расстояние между абзацами сохраняется и регулируется отдельно. У абзацев с выравниванием по центру или вправо красная строка не применяется.
smartPunctuation|=|Типографские тире, многоточие и двойные кавычки при вводе.|При последовательном наборе заменяет -- на —, ... на … и прямые двойные кавычки на «ёлочки». Уже написанный или вставленный текст целиком не обрабатывается. Замена двух дефисов также включается отдельной настройкой автоформата.
writerSyntax|Подсветка диалогов и мыслей|Разные акценты для кавычек и скобок.|Диалогом считается текст внутри «…» или прямых двойных кавычек, мыслью — текст в круглых скобках длиной от трёх символов. Это визуальная подсветка по знакам, без изменения текста. Реплики с тире без кавычек таким способом не распознаются.
readability|=|Подсветка коротких и длинных предложений.|Завершённые предложения из 1–7 слов подсвечиваются зелёным, предложения длиннее 24 слов — красным. Средняя длина не выделяется. Это ориентир для вычитки, а не оценка качества прозы; требуется поддержка подсветки диапазонов браузером.
strictSpellcheck|=|Подсветка совпадений со словарём ошибок проекта.|Использует встроенные и собственные правила для слов и фраз. Имена и названия из базы знаний, а также слова из личного словаря исключаются из проверки. Этот переключатель также нужен для дополнительной проверки Smart-словарём; исправления выбирает пользователь.
baselineGrid|Сетка строк|Горизонтальные направляющие по высоте строки.|Рисует линии на фоне абзацев и цитат с шагом текущего межстрочного интервала. Помогает оценить вертикальный ритм страницы. Сетка относится к рабочему редактору и не включается в экспорт.
smartDictionary|Дополнительная проверка слов|Экспериментальная проверка слов локально или через LanguageTool.|Работает только при включённой «Проверке частых ошибок». В офлайн-режиме использует локальные известные ошибки; онлайн-режимы дополняют их ответами LanguageTool. Это экспериментальная функция, а не полноценная проверка всех грамматических конструкций.
smartDictionaryMode|Режим дополнительной проверки|Выберите локальную проверку или подключение LanguageTool.|«Офлайн» не отправляет текст в сеть. «Словарь и LanguageTool» сначала проверяет локальные совпадения, затем обращается к сервису. «Онлайн» использует сервис только в дополнительной ветке: обычные правила проекта продолжают работать. В онлайн-запрос может попасть контекст абзаца до 4000 символов.
smartDictionaryLang|Язык проверки LanguageTool|Язык для онлайн-запросов.|Выберите автоматическое определение, украинский, русский или английский язык. Выбор влияет на LanguageTool и его кэш. В офлайн-режиме он не переключает локальную базу правил и не переводит текст.
dictionarySearch|Поиск правил|Искать по ошибке, исправлению или метке.|Фильтрует список правил по введённому тексту, без изменения самой проверки рукописи. На экране выводятся первые 180 совпадений. Чтобы найти остальные, уточните запрос или категорию.
dictionary-import|Импортировать правила|Добавить правила из JSON-файла.|Принимает массив правил или объект с полем rules. Правила с совпадающим нормализованным написанием обновляются, новые добавляются. Импорт меняет пользовательский словарь проекта, но не заменяет весь проект.
dictionary-export|Экспортировать правила|Сохранить пользовательские правила в JSON-файл.|Экспортирует сохранённые записи словаря, включая переопределения и отключения встроенных правил. Саму встроенную базу целиком эта кнопка не выгружает. Файл можно импортировать в другой проект.
dictionary-add|Добавить правило|Слово или фраза и предлагаемое исправление.|Открывает форму с неверным написанием, заменой, меткой и режимом сопоставления. Совпадение со встроенным правилом создаёт его переопределение. Создание правила не исправляет все совпадения автоматически.
dictionary-override|Изменить встроенное правило|Задать свой вариант исправления.|Встроенная запись сохраняется в базе приложения, а поверх неё создаётся пользовательское переопределение. Сброс переопределения возвращает исходное исправление. Изменяется правило проверки, а не текст рукописи.
dictionary-disable-builtin|Отключить правило|Не использовать встроенное правило в обычной проверке.|Правило остаётся в списке отключённых и может быть включено снова. В текущей экспериментальной офлайн-проверке Smart-словарь может повторно находить исходное совпадение; эта несогласованность требует исправления.
dictionary-enable-builtin|Включить правило|Вернуть встроенное правило в обычную проверку.|Убирает пользовательскую отметку отключения. Правило снова участвует в локальной проверке, если включена «Проверка частых ошибок». Отключённый общий переключатель этой кнопкой не включается.
dictionary-edit|Редактировать правило|Изменить написание, замену или метку.|Открывает существующее пользовательское правило или переопределение. Изменения вступают в силу после сохранения формы. Эта команда не является массовой заменой текста в документах.
dictionary-delete|Удалить правило|Убрать собственное правило из словаря.|Удаляет выбранную пользовательскую запись после подтверждения. Основной текст документов не изменяется. Удаление встроенного правила заменяется его отключением.
dictionary-reset-override|Вернуть встроенное исправление|Удалить своё переопределение правила.|Убирает пользовательскую версию и возвращает исходное исправление из встроенного словаря. Это не сброс всех правил или настроек проверки. Тексты документов остаются прежними.
rule:typo-wrong|=|Написание, которое нужно находить в тексте.|Введите слово или фразу для сопоставления. Пробельные последовательности нормализуются, сравнение не зависит от регистра. Для фразы выберите соответствующий режим; это не регулярное выражение.
rule:typo-correct|Предлагаемое исправление|Вариант замены, который увидит автор.|Исправление показывается при выборе подсвеченной ошибки. Сохранение правила само по себе не заменяет текст во всех главах. Поле должно содержать непустой вариант.
rule:label|Категория ошибки|Подпись правила в списке и подсказке.|Выберите «Мой словарь», «Частая ошибка», «Опечатка» или «Раздельно / слитно». Категория помогает читать список, но не меняет алгоритм сопоставления или важность ошибки.
rule:mode|Что искать|Отдельное слово или фразу.|«Слово» сопоставляет отдельный токен, «Фраза» — последовательность с границами слов и допустимыми пробелами. При открытии формы режим предварительно выбирается по наличию пробелов в исходном написании.
reviewMode:write|Письмо|Обычное редактирование текста.|Рукопись доступна для набора и изменения. Существующие редакторские пометки остаются в проекте; смена режима их не принимает и не удаляет. Выбор режима относится к рабочему интерфейсу приложения.
reviewMode:editor|Редактура|Комментарии и предложения без прямой правки текста.|Основной текст защищён от непосредственного редактирования. Можно оставлять пометки, комментарии и предложения замены. Для изменения самого текста переключитесь на «Письмо» или «Финализацию».
reviewMode:finalization|Финализация|Редактирование текста и обработка пометок.|Можно редактировать рукопись, переходить между редакторскими пометками и обрабатывать их. Смена режима сама по себе не принимает все предложения. Это этап работы, а не автоматическая подготовка финального файла.
exportNocturned|Сохранять пакет правок вместе с DOCX|Отдельный файл .nocturned для обмена редакторскими пометками.|После успешного экспорта текущей главы в DOCX дополнительно создаётся файл .nocturned, если у главы есть редакторские пометки. Это формат Nocturne, а не встроенные исправления Word. Один и тот же переключатель доступен в «Редактуре» и «Экспорте»; его вариант в поиске сейчас не связан с рабочим флагом.
bookmarkMode|=|Привязка для новой закладки без выделения.|«Точная позиция» отмечает место каретки, «Абзац» — текущий абзац. Если текст выделен, закладка сохраняет весь выделенный фрагмент независимо от этого выбора. Без выделения вариант «Фрагмент» использует текущий абзац.
bookmarkTitleLength|Длина названия закладки|Предел для автоматического названия абзаца или фрагмента.|Диапазон — 20–100 символов, исходное значение — 56. Название берётся из начала отмеченного текста и обрезается по установленному пределу. Точная позиция получает имя «Закладка N». Готовое название можно изменить вручную; старые названия ползунок не переписывает.
bookmarkFollowText|Перемещать закладку вслед за текстом|Сохранять связь с текстом при правках перед закладкой.|При вставке и удалении перед отмеченным местом его координаты обновляются. Если выключить, прежняя позиция не сдвигается вслед за правками и может указывать на другой текст. Полное удаление отмеченного текста регулируется отдельными настройками.
bookmarkCopyWithText|Копировать закладки вместе с текстом|Переносить метаданные при копировании внутри Nocturne.|По умолчанию выключено: скопированный текст не несёт закладок. При включении приложение сохраняет дополнительные сведения вместе с выделением для вставки в Nocturne. Невидимые символы в рукопись не добавляются; внешний редактор не обязан понимать эти метаданные.
bookmarkConfirmTextDeletion|Спрашивать при удалении текста с закладкой|Подтверждать полное удаление отмеченного места.|Если правка полностью уничтожает привязку, приложение показывает подтверждение. Отмена отменяет изменение текста. При частичном удалении абзаца или фрагмента закладка сохраняется на оставшейся части, без такого вопроса. Результат подтверждённого удаления задаётся следующим параметром.
bookmarkDeletedText|После удаления отмеченного текста|Что делать с закладкой, потерявшей весь свой текст.|«В корзину» удаляет закладку с возможностью восстановления. «Сохранить без привязки» оставляет запись для ручного восстановления связи. «К ближайшему месту» переносит её к месту удаления. Для сложенной закладки решение применяется к затронутой части.
bookmarkConfirmDeletion|Спрашивать при удалении закладки|Подтверждать ручной перенос закладки в корзину.|Относится к удалению самой закладки через её меню или список. Вопрос при удалении отмеченного текста настраивается отдельно. Отключение подтверждения не отключает корзину.
bookmarkVisibility|Показывать большой значок закладки|Выберите момент появления кнопки у отмеченного текста.|Маленькая метка остаётся видна постоянно. Большой значок может появляться при наведении или касании, только у активной закладки либо всегда. Для абзаца большой значок расположен справа; маленькая фигурная метка — слева.
bookmarkHighlight|Подсветка отмеченного текста|Показывать фон при переходе, постоянно или только метку.|У абзаца фон начинается от фигурной метки слева, у фрагмента относится к отмеченному тексту. Выбор «Только метка» убирает фоновую подсветку, но сохраняет малые обозначения закладок. Эта настройка не меняет выделение текста для копирования.
bookmarkBehavior|=|Порядок записей в списке закладок.|«По тексту» следует расположению в источнике, «По времени добавления» — времени создания, «Вручную» — установленному порядку. Сортировка не перемещает отмеченный текст. В режиме навигации «По списку» этот порядок используется и для переходов.
bookmarkNavigation|Переход между закладками|Откуда искать предыдущую и следующую закладку.|«По списку» переходит относительно выбранной записи с учётом порядка списка. «От каретки» ищет закладку относительно текущего места ввода. Переход прокручивает и подсвечивает закладку, не устанавливая каретку и не открывая клавиатуру телефона.
bookmarkWrap|Переходить по кругу|Продолжать навигацию за концом списка.|После последней записи команда «Следующая» переходит к первой, а перед первой «Предыдущая» — к последней. При выключении переход на противоположный конец списка не выполняется. Сами закладки не меняются.
bookmarkReopen|Позиция при открытии документа|Последнее место, выбранная закладка или начало.|«Последняя позиция» использует сохранённое состояние рабочей области для этого документа. «Последняя выбранная закладка» прокручивает к ней, если запись сохранилась. «Начало документа» прокручивает вверх. Переход к закладке не ставит каретку и не открывает клавиатуру.
bookmarkSnapshots|Закладки в снимках истории|Сохранять и восстанавливать закладки вместе со снимком текста.|Включено по умолчанию. Новые снимки включают закладки, а восстановление использует сохранённые данные при включённой настройке. Выключение не удаляет текущие закладки и не переписывает старые снимки; оно меняет участие закладок в истории.
showZenButton|Кнопка «Дзен»|Показывать кнопку режима концентрации.|Управляет видимостью кнопки быстрого входа в «Дзен» в рабочем интерфейсе. Если выключить настройку во время активного «Дзен», приложение выйдет из режима. Остальные настройки фокуса регулируются отдельно.
sentenceFocus|Фокус на абзаце|Приглушать соседние блоки вокруг места ввода.|Ярким остаётся текущий блок текста, соседние блоки становятся менее заметными. Отдельное предложение внутри абзаца эта настройка не выделяет. Во время выделения текста приглушение снимается, чтобы выделение было видно целиком.
autoPaginate|Постраничный вид|Показывать рукопись на листах с полями.|Включает визуальную раскладку редактора на страницы. Текст остаётся единым документом, а экспорт оформляется отдельно. Это не движок Microsoft Word и не обещание одинаковых разрывов страниц в DOCX. По умолчанию выключено.
showPageRulers|Линейки страниц|В текущей версии линейки ещё не отображаются.|Настройка сохраняется, но отрисовка линеек к ней не подключена. Она сейчас не меняет поля, текст или экспорт. Перед публикацией полноценного описания нужно реализовать линейки либо убрать недействующий пункт из интерфейса.
writingAnimation|=|Эффект возле набираемого символа.|«Искры», «Волна» и «Туман» — декоративные эффекты около места ввода. «Выключено» отключает их. Эффект относится к набору символов и не анимирует весь вставленный текст; уменьшение движения может дополнительно сокращать анимации.
dailyGoal|Дневная цель|Число слов для дневного прогресса.|Диапазон — 100–10000 слов с шагом 100. Используется накопленная статистика письма за день, а не просто длина открытой главы. Изменение цели меняет шкалу прогресса и порог достижения цели; на телефоне статистика сохраняется без нижнего индикатора боковой панели.
showDontTell|Подсветка слабых формулировок|Обратить внимание на слова из короткого списка.|Локально выделяет фиксированный набор слов и выражений, например «очень», «внезапно» и «как будто». Настройка не анализирует смысл сцены и не определяет, как заменить объяснение действием. Подсветка служит поводом проверить фразу вручную.
dialogueLens|Фокус на диалогах|Приглушить текст в кавычках или вне них.|«Только диалоги» оставляет заметными фрагменты в распознанных кавычках, «Только описания» — остальной текст. Реплики с тире без кавычек не распознаются этим способом. Фокус меняет только отображение, не содержание и не экспорт.
new-macro-keys|=|Комбинация, которая вставит заданный текст.|На компьютере нажмите «Записать», затем введите сочетание. На телефоне поле допускает ручной ввод, но выполнение требует соответствующих событий клавиатуры. Комбинации сопоставляются с физическими клавишами независимо от раскладки; конфликты показываются отдельно.
macro-record-toggle|Записать сочетание|Считать клавиши для нового макроса.|После включения записи нажмите нужные клавиши и модификаторы. Повторное нажатие кнопки завершает запись. Запись не создаёт макрос, пока не заполнен вставляемый текст и не нажата кнопка «Добавить макрос».
new-macro-value|Вставляемый текст|Символ или короткая фраза до 50 символов.|Этот текст вставляется при выполнении сочетания в редактируемой рукописи. Макрос может содержать несколько символов, а не только один знак. Начальные и конечные пробелы обрезаются; запись только из пробелов не сохраняется.
macro-save-new|Добавить макрос|Сохранить сочетание и вставляемый текст.|Если такая комбинация уже существует, её текст обновляется. Некоторые системные сочетания запрещены, а известные конфликты показываются в форме. Макрос выполняет вставку текста, а не последовательность команд приложения.
macro-delete|Удалить макрос|Убрать выбранное сочетание.|Перед удалением открывается подтверждение с комбинацией и вставляемым текстом. Уже вставленный в рукопись текст остаётся прежним. Удаление не переназначает другие горячие клавиши.
autoReplaceDoubleDash|Два дефиса → длинное тире|Заменять -- на — при наборе.|Замена срабатывает при вводе второго дефиса. Быстрый Backspace в том же месте возвращает --. Она действует, если включён этот параметр или «Умная пунктуация»: для полного отключения выключите оба. Вставленный текст целиком не переписывается.
autoReplaceEnDash|Отдельный дефис → среднее тире|Заменять пробел-дефис-пробел на тире.|Замена срабатывает при наборе пробела после одиночного дефиса, перед которым уже есть пробел. Дефис внутри слова не меняется. Это правило ввода, а не проверка наличия двух слов по обе стороны знака.
new-rule-trigger|Текст для срабатывания|Последовательность до 15 символов в начале блока.|Правило сравнивается с текстом от начала текущего блока до каретки после нажатия Пробела или обычного Enter. Совпадение в середине произвольной фразы не запускает правило. Запись с тем же триггером заменяет прежнее правило.
newRuleAction|Действие правила|Выравнивание, заголовок или разделитель.|Выравнивание по центру или вправо сохраняет сам триггер. Заголовки H2/H3 и линия удаляют его. «Свой текст» заменяет блок центрированным разделителем и создаёт следующий пустой абзац. Выбор здесь применяется только после сохранения нового правила.
new-rule-custom-text|Текст разделителя|Символы, которые заменят триггер.|Поле используется только для действия «Свой текст». Допустимо до 30 символов; пустое значение не сохраняется. Получится центрированный текстовый абзац, а не графическая горизонтальная линия.
formatting-save-new|Добавить правило|Сохранить триггер и выбранное действие.|Новое правило сразу включается. Если такой триггер уже есть, его действие обновляется. Изменение формы без нажатия этой кнопки не создаёт правило в списке.
formatting-toggle-rule|Использовать правило|Включить или приостановить выбранное правило.|Выключенная запись остаётся в списке со своим триггером и действием, но не срабатывает при наборе. Это переключатель отдельного правила, а не всех замен пунктуации.
formatting-delete|Удалить правило|Убрать выбранный триггер из списка.|Удаляет сохранённую запись автоформата; отдельного подтверждения в этой ветке нет. Уже оформленные заголовки и разделители в документе остаются прежними.
aiProvider|Провайдер ИИ|Сервис или локальный сервер для генерации.|«Не настроен» отключает генерацию. Ollama требует отдельно запущенного сервера модели; на телефоне localhost означает сам телефон. Облачные сервисы требуют подходящих адреса, модели и ключа. Обычная смена встроенного провайдера подставляет его адрес и модель; бесплатность выбранного сервиса не гарантируется.
aiEndpoint|Адрес API|URL, на который отправляются запросы ИИ.|Укажите полный адрес API нужного формата. Для локального сервера на другом устройстве нужен его доступный сетевой адрес. В прямом формате Gemini модель задаётся в самом URL; поле модели отдельно его не переписывает.
aiKey|Ключ API|Ключ для доступа к выбранному сервису.|Ключ сохраняется локально в данных приложения, а при запросе передаётся выбранному провайдеру. При включённом шифровании локальное сохранение ключей защищается; без него это не системное хранилище секретов. Для стандартной локальной Ollama ключ обычно не требуется.
aiModel|Модель ИИ|Идентификатор модели выбранного сервиса.|Используется в запросах OpenAI-совместимого формата, Ollama и Anthropic. В прямом формате Gemini модель берётся из URL, поэтому изменение только этого поля не меняет её. Имя должно соответствовать реально доступной модели сервера.
test-ai-connection|=|Минимальный запрос для проверки текущей конфигурации.|Проверяет текущие адрес, формат, модель и ключ с помощью настоящего запроса. Для внешнего сервиса это сетевой вызов, на который распространяются его лимиты и тариф. Успех подтверждает доступность тестового запроса, а не всех функций ассистента.
aiPersona|Персона ассистента|Роль и стиль рекомендаций ИИ.|«Злой критик», «Муза» и «Соавтор» задают разные системные инструкции. Можно создать собственную персону. Персона влияет на запрос к модели, но не меняет режим «Письмо / Редактура / Финализация» и не запускает генерацию сама.
aiTemperature|Креативность ответа|Температура запросов к модели.|Диапазон — 0–1,4 с шагом 0,05. Меньшие значения обычно делают формулировки устойчивее, большие — разнообразнее. Параметр не гарантирует качество ответа: доступный диапазон и его обработка зависят от выбранного сервера.
aiKnowledgeContext|=|Использовать сведения о мире в запросах ассистента.|Ассистент получает отобранные данные базы знаний, связанной с документом, в пределах ограниченного объёма контекста. Текст справки не вставляется в рукопись. Если используется внешний провайдер, включённые сведения передаются ему вместе с запросом.
edit-world-rules|=|Текстовые ограничения и закономерности вашего мира.|Открывает правила текущей базы знаний: по одному правилу на строку. Они могут включаться в справочный контекст ассистента. Сами по себе эти записи не запускают автоматическую проверку и не блокируют сохранение рукописи.
aiContextGroups|Состав контекста|Какие сведения базы знаний доступны ассистенту.|Переключатели ниже исключают целые группы из справочного контекста. Они действуют только при включённом «Контексте базы знаний» и не удаляют сами записи. Правила мира имеют отдельный внутренний флаг, но его переключателя в этой группе сейчас нет.
aiContextCharacters|Персонажи|Профили персонажей в контексте ИИ.|Разрешает отбирать релевантные сведения о персонажах. Не означает отправку всей коллекции в каждый запрос: применяется ограничение объёма и отбор контекста. Работает вместе с общим переключателем контекста.
aiContextLocations|Локации|Места и их описания в контексте ИИ.|Разрешает включать сведения о локациях из базы знаний документа. Выключение влияет только на новые запросы ассистента. Карточки локаций и упоминания в рукописи не удаляются.
aiContextTimeline|Хронология|Основные события мира в контексте ИИ.|Разрешает включать релевантные события основной хронологии. Вложенные события управляются соседним переключателем. При выключенном общем контексте этот выбор не отправляет никаких сведений.
aiContextSubtimelines|Вложенные события|События внутри хронологии в контексте ИИ.|Разрешает включать сведения о вложенных событиях. Это дополнение к основной хронологии, а не отдельный источник генерации. Приложение по-прежнему ограничивает общий объём справочного контекста.
aiContextNotes|Записи|Записи базы знаний в контексте ИИ.|Разрешает отбирать записи из базы знаний, относящейся к документу. Здесь речь о записях мира, а не о каждом плавающем окне заметки. Выключение группы не меняет сами записи.
loreStrictness|Строгость проверки лора|Проверка лора сейчас не использует этот параметр.|Ползунок сохраняет число от 0 до 100 %, но в текущей версии оно не подключено к поиску противоречий. Изменение значения не делает проверку строже. Для рабочего описания требуется реализация проверки или удаление недействующего пункта.
loreReaction|Действие при конфликте лора|Реакция на противоречия пока не подключена.|Выбор сохраняется, но текущий код не применяет его к проверке или сохранению текста. Даже вариант «Блокировать сохранение абзаца» сейчас не блокирует запись. До реализации поведения нельзя обещать автору такую защиту.
sentimentTimeline|График тональности|Локальная оценка эмоционального тона последних предложений.|Включает небольшой график, основанный на локальных списках положительных и отрицательных слов. Это приблизительная оценка тона, а не анализ сюжетного напряжения моделью ИИ. Подключение провайдера для него не требуется.
liveSave|Черновики при вводе|Дополнительное локальное сохранение текущего текста.|При изменениях создаёт рабочий черновик для восстановления. Основное сохранение документов работает отдельно и не отключается этим переключателем. Для зашифрованных данных применяется локальная защита; восстановление может требовать пароль, поэтому абсолютной гарантии последнего введённого символа здесь нет.
autosaveMinutes|Интервал фонового сохранения|Период сохранения открытых документов и автоматических копий.|В интерфейсе доступны 1–15 минут с шагом 1 минута. По таймеру сохраняются открытые документы и общие заметки; при включении соответствующих параметров создаются резервная копия и версия Git. Обычное сохранение после редактирования работает независимо от этого таймера.
manual-snapshot|История текста|Снимки состояния перед важными изменениями.|«Создать снимок» сохраняет текст текущей главы, её заметки и связанные данные истории. «История» позволяет открыть сохранённые версии и восстановить выбранную. Закладки включаются согласно отдельному параметру; снимок главы не равен резервной копии всего проекта.
open-backups|=|Резервные копии всего проекта и восстановление.|Список приложения хранит последние 20 записей копий. В Electron и Android используются платформенные папки, в браузере копии могут храниться локально или в подключённой папке. Очистка старых записей списка не гарантирует удаление соответствующих файлов из внешней папки.
automaticBackups|Автоматические резервные копии|Создавать копию проекта по таймеру фонового сохранения.|Включено по умолчанию. Полная копия создаётся с заданным интервалом, если проект доступен для сохранения; для зашифрованного проекта нужен пароль сессии. Выключение прекращает автоматические копии, но не удаляет существующие и не запрещает ручное создание.
open-trash|=|Просмотр и восстановление удалённых объектов.|Открывает категории удалённых документов, объектов базы знаний и прочих данных, включая закладки. Восстановление доступно для сохранённых записей корзины. Полный сброс проекта очищает также корзину, поэтому не относится к обычному удалению.
open-sync-conflicts|=|Сравнение версий, изменённых на разных устройствах.|Можно выбрать локальную или другую версию, а для подходящего конфликта документов сохранить обе главы. Разрешение меняет запись и состояние конфликта. Это не настройка подключения и не автоматическое соединение устройств.
gitVersioning|История проекта в Git|Дополнительные версии на этом компьютере.|Доступно в Electron и требует установленного Git. Приложение записывает снимок проекта в локальный репозиторий по таймеру и при создании версии. Эта настройка не подключает GitHub, не отправляет проект в облако и не заменяет обычное сохранение.
e2e|Шифрование локальных данных|Защита чувствительных данных мастер-паролем.|Включение требует пароль и переводит чувствительные записи в зашифрованный вид. Служебные идентификаторы, даты и часть настроек остаются открытыми. Для чтения нужен правильный пароль; отправка текста выбранному ИИ и явный открытый экспорт регулируются отдельно.
save-password|Пароль текущей сессии|Открыть зашифрованные данные в этой сессии.|После «Применить» приложение перечитывает защищённые записи с указанным паролем. Это ввод существующего пароля, а не отдельная команда смены пароля всех данных. Сообщение о применении не доказывает, что пароль подходит ко всем записям: неподходящие остаются заблокированными.
reset-settings|=|Вернуть параметры приложения к исходным значениям.|Документы, база знаний, заметки и снимки остаются. Сбрасываются также собственные шрифты, макросы, провайдеры, ключи и персоны, хранящиеся в настройках. Состояние шифрования сохраняется, а режим работы и рабочий флаг .nocturned сейчас сбрасываются отдельно от этих настроек и этой кнопкой не меняются.
authorName|=|Автор в DOCX и подпись водяного знака PDF.|Текст записывается в метаданные DOCX и используется в подписи PDF, если включён водяной знак. Это не имя учётной записи, не подпись каждого абзаца и не название проекта. Исходное значение — «Автор».
watermark|=|Полупрозрачная подпись автора и дата.|Добавляет подпись в печатный PDF-макет. Имя берётся из соседнего поля «Имя автора». Настройка не добавляет знак в DOCX и не меняет текст рукописи.
exportIncludeNotes|=|Добавлять заметки главы в её экспорт DOCX.|По умолчанию личные заметки не включаются. При включении экспорт текущей главы дополняется её заметками и поддерживаемыми связанными заметками; это не экспорт всех записей базы знаний. Параметр относится к DOCX главы, а не ко всем форматам.
export-book|Экспорт книги в DOCX|Выберите главы для одного файла.|Открывает выбор глав и собирает один документ в порядке томов и глав. Это отдельный сценарий экспорта книги, а не экспорт только активной главы. Само нажатие открывает настройку состава, прежде чем создать файл.
export-html|Подготовить PDF|Открыть макет для печати или сохранения в PDF.|Формируется печатный HTML-макет рукописи. Итоговое сохранение PDF выполняется через механизм печати платформы. Эта кнопка не гарантирует немедленное скачивание готового PDF-файла без дополнительного шага.
export-docx|Экспортировать главу в DOCX|Word-совместимый файл текущей главы.|Создаёт DOCX с текстом, заголовками и метаданными текущего документа. Заметки включаются по отдельной настройке. Если включён пакет правок и есть пометки, дополнительно создаётся .nocturned; сами пометки не превращаются в Word Track Changes.
export-project-dump|Экспортировать проект|Файл .nocturnedump с данными проекта.|Сохраняет главы, базы знаний, заметки, закладки, правки и настройки в переносимый формат Nocturne. Защищённые данные обычно сохраняются с шифрованием; открытый экспорт требует отдельного явного выбора. Это резервный файл проекта, а не документ для чтения.
import-project-dump|Импортировать проект|Открыть файл .nocturnedump.|После выбора файла приложение предлагает заменить текущий проект или объединить данные. При замене старое состояние перезаписывается; объединение добавляет данные с обработкой совпадающих идентификаторов. Восстановление рабочего флага экспорта .nocturned из файла сейчас неполное.
show-whats-new|Что нового|Список изменений установленной версии.|Открывает описание выпуска, включённое в эту сборку приложения. Не проверяет наличие обновлений в интернете и не скачивает новую версию. История содержит текущий и предыдущие выпуски.
compactPanels|Панель документов|Уменьшить ширину боковой панели рукописи.|Делает панель документов компактнее на компьютере, оставляя больше места рабочей области. Это не полное скрытие панели. В мобильном интерфейсе используется отдельная навигация, поэтому эффект отличается от настольного.
compactKbSidebar|Панель базы знаний|Уменьшить ширину боковой панели базы знаний.|Сокращает ширину настольной панели базы знаний, чтобы освободить место для содержимого. Карточки и их порядок не меняются. Для плотности самих карточек есть отдельный переключатель.
cardView|Карточки базы знаний|Показывать персонажей и локации компактным списком.|Переключает представление карточек между сеткой и списком. Это влияет на расположение карточек персонажей и локаций, не удаляет изображения или данные. Исходное представление — сетка.
compactToolbar|Панель инструментов|Уменьшить отступы между инструментами редактора.|Делает настольную панель инструментов плотнее. Набор команд остаётся тем же; это не настройка размера текста рукописи. Мобильная панель использует собственную раскладку.
compactSettings|Настройки|Уменьшить отступы в меню настроек.|Позволяет видеть больше параметров в настольном окне настроек. Названия, значения и порядок разделов сохраняются. Не является общим переключателем компактности всех панелей.
compactNotes|Панель заметок|Уменьшить отступы списка заметок.|Делает список заметок плотнее, чтобы помещалось больше записей. Текст, порядок и состояние заметок не меняются. Отдельные плавающие окна заметок не превращаются в компактный список.
provider:name|=|Имя сервера или сервиса в списке провайдеров.|Используется как подпись вашей конфигурации в выборе провайдера. Можно указать любое понятное имя. Название не определяет формат API, адрес или модель — эти параметры задаются отдельно.
provider:endpoint|Адрес API|Полный URL сервера нужного формата.|Укажите адрес конкретного API, а не просто главной страницы сервиса. Например, OpenAI-совместимый сервер обычно использует путь chat/completions. Для сервера на другом устройстве localhost не подходит; доступность сети проверяется отдельно.
provider:key|Ключ API, если нужен|Оставьте пустым для сервера без авторизации.|Ключ сохраняется вместе с этой конфигурацией и передаётся ей при запросе в соответствии с выбранным форматом API. Шифрование локальных ключей зависит от общей настройки защиты. Поле не создаёт ключ на стороне сервиса.
provider:model|=|Название модели, доступное на сервере.|Укажите точный идентификатор из конфигурации выбранного сервера. Для прямого формата Gemini модель задаётся адресом запроса. Сохранение конфигурации не загружает и не устанавливает модель.
provider:apiFormat|=|Протокол запросов выбранного сервера.|OpenAI-compatible, Ollama, Gemini и Anthropic используют разные структуры запросов и заголовки. Выберите формат, который поддерживает ваш endpoint. Формат не преобразует несовместимый сервер в совместимый.
persona:new-persona-name|Название персоны|Подпись роли в списке ассистента.|Имя помогает выбрать собственную персону среди встроенных и пользовательских. Оно не заменяет системную инструкцию и не определяет поведение модели само по себе. Пустое имя не сохраняется.
persona:new-persona-prompt|Системная инструкция|Какую роль и стиль должен использовать ассистент.|Текст включается в инструкцию для модели при выборе этой персоны. Здесь можно описать задачи, тон и ограничения. Пустая инструкция не сохраняется; соблюдение пожеланий зависит от ответа модели, а не от жёсткой блокировки редактора.
persona:edit-persona-name|Название персоны|Изменить имя существующей роли.|Меняет подпись выбранной пользовательской персоны. Системная инструкция редактируется отдельно в этом же окне. Сохранение не переписывает уже полученные ответы.
persona:edit-persona-prompt|Системная инструкция|Изменить инструкцию существующей роли.|Новый текст будет использоваться в следующих запросах с этой персоной. Он не выполняется как код и не меняет сохранённую рукопись сам по себе. Для применения заполните оба поля и сохраните форму.
rules|Правила мира|По одному правилу на строку.|Сохраняет текстовые правила текущей базы знаний. Пустые строки пропускаются; существующие записи по возможности сохраняют свои идентификаторы. Эти сведения используются как контекст ассистента, а не как действующий запрет на сохранение текста.
settings-search-field|Поиск настроек|Найти параметр по названию или описанию.|Результаты строятся из отдельного реестра и ссылок на разделы. Сейчас реестр содержит не все доступные поля и некоторые устаревшие тексты; отсутствие результата не означает отсутствия настройки. Переход в раздел позволяет увидеть его полный состав.
'''


def apply_specs(block):
    for line in block.strip().splitlines():
        key, title, short, long = line.split('|', 3)
        if key not in by_key:
            raise ValueError('Editorial entry without captured control: ' + key)
        item = by_key[key]
        for field, value in [('title', title), ('short', short), ('long', long)]:
            if value != '=':
                item['proposed'][field] = value


apply_specs(SPECS)

apply_specs('''
dictionary-filter:all|Все|Показать правила всех категорий.|Объединяет собственные, встроенные, отключённые и переопределённые правила в списке. Поиск продолжает действовать вместе с фильтром. Фильтр меняет только список, а не участие правил в проверке.
dictionary-filter:mine|Мои|Показать собственные правила.|Выводит правила, добавленные пользователем. Переопределения встроенных правил находятся в своей категории. Выбор не отключает встроенную проверку рукописи.
dictionary-filter:builtin|Встроенные|Показать исходные активные правила.|Не включает записи, которые вы отключили или переопределили. Такие записи доступны в отдельных категориях. Фильтр не восстанавливает исходные значения автоматически.
dictionary-filter:disabled|Отключённые|Показать отключённые встроенные правила.|Из этой категории правило можно включить снова. Сам выбор категории не включает его и не выключает другие правила. Общая проверка управляется отдельным переключателем.
dictionary-filter:override|Изменённые встроенные|Показать свои версии встроенных правил.|Здесь находятся пользовательские переопределения исходных исправлений. Для возвращения исходного варианта используйте сброс конкретного переопределения. Это отдельная категория, а не все собственные правила.
apply-ai-preset:gemini|Настроить Gemini|Подставить адрес и модель Gemini для совместимого API.|Пресет выбирает OpenAI-совместимый формат Gemini, подставляет адрес Google и gemini-2.5-flash. Текущий ключ очищается, затем нужно ввести ключ сервиса. Это отличается от прямого формата Gemini; доступность модели и условия использования проверяются у провайдера.
apply-ai-preset:groq|Настроить Groq|Подставить адрес и модель Groq.|Пресет выбирает Groq, подставляет его адрес API и модель llama-3.1-8b-instant. Текущий ключ очищается; после этого введите ключ Groq. Настройка не создаёт аккаунт и не гарантирует бесплатный доступ.
apply-ai-preset:openrouter|Настроить OpenRouter|Подставить адрес OpenRouter и модель-маршрутизатор.|Пресет использует OpenAI-совместимый формат, адрес OpenRouter и модель openrouter/free. Текущий ключ очищается. Название модели в конфигурации не гарантирует доступность или неизменность бесплатных лимитов сервиса.
apply-ai-preset:mistral|Настроить Mistral|Подставить адрес и модель Mistral.|Пресет использует совместимый формат запросов, API Mistral и модель mistral-small-latest. Текущий ключ очищается. Доступность модели, тарифа и лимиты определяются вашим аккаунтом у провайдера.
new-custom-provider|Добавить провайдера|Сохранить свою конфигурацию сервера ИИ.|Открывает поля названия, адреса, ключа, модели и формата API. Можно настроить совместимый облачный или локальный сервер. Создание записи не устанавливает сервер и не проверяет подключение автоматически.
edit-custom-provider|Редактировать провайдера|Изменить существующую конфигурацию ИИ.|Поля открываются с сохранёнными значениями выбранной записи. После сохранения новые запросы используют обновлённую конфигурацию. Уже созданные ответы и текст рукописи не переписываются.
delete-custom-provider|Удалить провайдера|Убрать свою конфигурацию из списка.|Удаление требует подтверждения. Если запись была выбрана, генерация возвращается в режим «Не настроен». Сохранённая конфигурация переносится в корзину настроек; это не удаление аккаунта или модели на сервере.
new-custom-persona|Создать персону|Задать свою роль и инструкцию ассистента.|Нужно заполнить имя и системную инструкцию. Новая роль появляется в выборе персоны, но не запускает запрос автоматически. Она не меняет выбранного провайдера или модель.
edit-custom-persona|Редактировать персону|Изменить имя и инструкцию собственной роли.|Открывает сохранённые поля персоны. Изменения используются в следующих запросах после сохранения. Встроенные роли редактированием пользовательской записи не заменяются.
delete-custom-persona|Удалить персону|Убрать собственную роль из списка.|Требует подтверждения. Если удалена выбранная роль, используется встроенный «Соавтор». Запись сохраняется в корзине настроек; полученные раньше ответы остаются прежними.
clear-all-docs|Удалить все документы и папки|Перенести рукопись и её структуру в корзину.|После подтверждения удаляются все главы и папки, а рабочая область очищается. Используется обычный механизм удаления документов с сохранением связанных данных для восстановления. В текущем подтверждении ещё есть неверное обещание «безвозвратно» — его нужно согласовать с корзиной.
clear-all-characters|Удалить всех персонажей|Очистить персонажей текущей базы знаний.|После подтверждения удаляются персонажи выбранного произведения, а удалённые записи сохраняются механизмом корзины. Другие базы знаний не очищаются. Это не удаление упоминаний персонажей из текста глав.
clear-all-locations|Удалить все локации|Очистить локации текущей базы знаний.|Удаляются записи мест выбранного произведения, с сохранением удалённых объектов в корзине. Локации других произведений и основной текст документов остаются. Действие требует подтверждения.
clear-all-notes|Удалить все записи базы знаний|Очистить записи текущего произведения.|После подтверждения удаляется коллекция записей текущей базы знаний. Заметки глав, общие заметки и плавающие окна этим действием не очищаются. Удалённые записи передаются в корзину.
clear-all-timeline|Удалить всю хронологию|Очистить события текущего произведения.|Удаляются основные события вместе с вложенными событиями текущей базы знаний. Другие произведения не затрагиваются; связанные удалённые объекты сохраняются в корзине. Текущий просмотр вложенного события закрывается.
clear-all-kb|Очистить текущую базу знаний|Удалить персонажей, локации, события и записи этого мира.|Очищает четыре коллекции выбранного произведения после подтверждения, с сохранением удалённых объектов в корзине. Остальные произведения не затрагиваются. Правила мира этой веткой не очищаются, поэтому название «полностью» для всей базы некорректно.
reset-data|Удалить все данные проекта|Полный сброс, включая корзину и резервные данные.|После подтверждения очищаются локальные данные проекта и создаётся исходное состояние. В отличие от обычного удаления, этот сценарий не оставляет данные в корзине. Перед использованием сохраните внешний файл проекта, если потребуется восстановление.
demo-add-docs|=|Создать примеры глав в локальном проекте.|Добавляет встроенные главы с признаком демо и создаёт недостающие исходные папки. Повторный запуск не дублирует те же демо-идентификаторы. Это реальные записи проекта, а не временный показ интерфейса.
demo-remove-docs|=|Удалить главы, отмеченные как демо.|После подтверждения удаляются демо-главы и связанные данные. Исправленная пользователем демо-глава всё ещё считается демо, пока сохраняет свою маркировку. Обычные главы без такого признака не выбираются для удаления.
demo-add-lore|Добавить примеры персонажей и локаций|Демо-карточки в текущей базе знаний.|Добавляет встроенные персонажи и места в выбранное произведение. Связи с главами переводятся на соответствующие демо-документы. Другие произведения не наполняются автоматически.
demo-remove-lore|Удалить примеры персонажей и локаций|Убрать карточки с маркировкой демо.|Удаляются демо-карточки текущего произведения, включая изменённые вами карточки, если признак демо остался. Пользовательские карточки без такой маркировки не выбираются. Для удаления применяется сохранение объектов в корзине.
demo-add-timeline|Добавить примеры событий|Демо-хронология текущего произведения.|Создаёт встроенные события и вложенные примеры в выбранной базе знаний. Уже существующие демо-идентификаторы не добавляются повторно. Это не генерация событий по рукописи.
demo-remove-timeline|Удалить примеры событий|Убрать события с маркировкой демо.|Удаляет отмеченные демо-события и вложенные примеры. Если вы добавили своё событие внутрь удаляемого демо-родителя, оно уходит вместе с ним. Поэтому обещать сохранность всех пользовательских вложений нельзя.
demo-add-all|=|Добавить примеры глав, персонажей, мест и событий.|Последовательно выполняет три операции добавления демо. Набор сохраняется в локальном проекте и может участвовать в его экспорте. Это не временное включение демонстрационного режима.
demo-remove-all|=|Убрать все объекты с демо-маркировкой.|После подтверждения удаляет демо-главы, демо-карточки и демо-хронологию. Изменённые демо-объекты не становятся обычными автоматически. Пользовательские вложения внутри удаляемого демо-родителя могут удалиться вместе с ним.
clear-temp-notes|=|Закрыть и убрать несохранённые временные окна.|Удаляет только плавающие заметки с признаком temporary в текущем состоянии приложения. Постоянные заметки, записи базы знаний и заметки глав не выбираются. Временные окна не являются сохранёнными записями базы.
clear-current-review-marks|Удалить пометки текущей главы|Перенести её редакторские пометки в корзину.|После подтверждения удаляются пометки активного документа. Предложенные изменения не принимаются, а основной текст остаётся прежним. Пометки других глав не выбираются; удалённые записи сохраняются в корзине.
reset-hidden-floating-notes|Показать скрытые заметки|Открыть скрытые постоянные плавающие окна.|Снимает признак скрытия у постоянных заметок и показывает их в текущем интерфейсе. Текст и расположение не сбрасываются. Временные скрытые окна этой командой не изменяются.
''')

